/**
 * Authentication Endpoints Router
 * Exposes authentication middleware functions as API endpoints
 */

import { Router } from 'express';
import { 
  login, 
  register, 
  logout, 
  changePassword, 
  forgotPassword, 
  resetPassword,
  authenticate 
} from '../middleware/auth';
import { validateRequest } from '../middleware/validateRequest';
import { authRateLimiter } from '../middleware/rateLimiter';
import { z } from 'zod';

const router = Router();

// Validation schemas
const loginSchema = z.object({
  email: z.string().email('Invalid email format'),
  password: z.string().min(1, 'Password is required'),
});

const registerSchema = z.object({
  email: z.string().email('Invalid email format'),
  password: z.string().min(8, 'Password must be at least 8 characters'),
  name: z.string().min(1, 'Name is required'),
  organizationId: z.number().optional(),
});

const changePasswordSchema = z.object({
  currentPassword: z.string().min(1, 'Current password is required'),
  newPassword: z.string().min(8, 'New password must be at least 8 characters'),
});

const forgotPasswordSchema = z.object({
  email: z.string().email('Invalid email format'),
});

const resetPasswordSchema = z.object({
  token: z.string().min(1, 'Reset token is required'),
  newPassword: z.string().min(8, 'New password must be at least 8 characters'),
});

// Public endpoints with rate limiting
router.post('/login', authRateLimiter, validateRequest(loginSchema), login);
router.post('/register', authRateLimiter, validateRequest(registerSchema), register);
router.post('/forgot-password', authRateLimiter, validateRequest(forgotPasswordSchema), forgotPassword);
router.post('/reset-password', authRateLimiter, validateRequest(resetPasswordSchema), resetPassword);

// Protected endpoints
router.post('/logout', authenticate, logout);
router.post('/change-password', authenticate, validateRequest(changePasswordSchema), changePassword);

// Session check endpoint
router.get('/me', authenticate, (req, res) => {
  res.json({
    user: {
      id: req.user!.id,
      email: req.user!.email,
      name: req.user!.name,
      role: req.user!.role,
    },
  });
});

export default router;